from datetime import date

import pytest

from exposed.adapters.postgres import PostgresStore, connect
from exposed.core.errors import ImportFailed, ImportValidationError, SourceError
from exposed.core.models import CommonsService, Member
from exposed.core.refresh import refresh_members
from tests.fakes import AS_OF, TERM_START
from tests.memory import MemorySource, MemoryStore


@pytest.fixture(params=["memory", pytest.param("postgres", marks=pytest.mark.integration)])
def store(request):
    if request.param == "memory":
        yield MemoryStore()
    else:
        with connect(request.getfixturevalue("database_url")) as conn:
            yield PostgresStore(conn)


def test_storage_port_preserves_completed_batches_before_allowing_a_retry(store):
    class FailingSource(MemorySource):
        def commons_candidates(self, term_start, as_of):
            yield self.profiles[:1]
            raise SourceError("Required member source unavailable")

    with pytest.raises(ImportFailed, match="source unavailable"):
        refresh_members(TERM_START, AS_OF, FailingSource(), store)

    retried = refresh_members(TERM_START, AS_OF, MemorySource(), store)
    repeated = refresh_members(TERM_START, AS_OF, MemorySource(), store)

    assert (retried["inserted"], retried["unchanged"]) == (1, 1)
    assert (repeated["inserted"], repeated["unchanged"]) == (0, 2)


def test_storage_port_rejects_a_different_term_without_changing_completed_data(store):
    refresh_members(TERM_START, AS_OF, MemorySource(), store)

    with pytest.raises(ImportFailed, match="another term"):
        refresh_members(date(2024, 7, 9), AS_OF, MemorySource(), store)

    result = refresh_members(TERM_START, AS_OF, MemorySource(), store)
    assert (result["inserted"], result["updated"], result["unchanged"]) == (0, 0, 2)


@pytest.mark.parametrize("failure_type", [ImportValidationError, KeyboardInterrupt])
def test_storage_port_rolls_back_active_batch_on_validation_failure_or_interruption(
    store, failure_type
):
    source = MemorySource()
    refresh_members(TERM_START, AS_OF, source, store)
    member = Member.from_profile(source.profiles[0], is_current_commons=True)
    changed = member.model_copy(update={"name": "Must roll back"})
    service = CommonsService.from_history(
        source.member_histories({1})[0],
        term_start=TERM_START,
        as_of=AS_OF,
        is_current_commons=True,
    )

    with pytest.raises(failure_type), store.refresh_batch(TERM_START) as writer:
        assert writer.write_member(changed, service.periods) == "updated"
        raise failure_type()

    result = refresh_members(TERM_START, AS_OF, source, store)
    assert (result["inserted"], result["updated"], result["unchanged"]) == (0, 0, 2)
from decimal import Decimal
from uuid import UUID

import pytest

from exposed.adapters.declaration_postgres import PostgresDeclarationStore
from exposed.adapters.postgres import connect
from exposed.core.declarations import DeclarationDraft, FundingEntry
from exposed.core.errors import ImportFailed, SourceError
from exposed.core.refresh_declarations import refresh_declarations
from tests.declaration_memory import MemoryDeclarationSource, MemoryDeclarationStore
from tests.fakes import TERM_START, ParliamentFixture
from tests.test_importer import run as import_members


@pytest.fixture(params=["memory", pytest.param("postgres", marks=pytest.mark.integration)])
def declaration_store(request):
    if request.param == "memory":
        store = MemoryDeclarationStore(TERM_START, {1: UUID(int=1), 2: UUID(int=2)})
        yield (
            store,
            lambda: {id: d.funding[0].amount for id, (d, _) in store.records.items()},
        )
    else:
        url = request.getfixturevalue("database_url")
        import_members(url, ParliamentFixture(2))

        def amounts():
            with connect(url) as reader:
                return {
                    r["source_declaration_id"]: r["amount"]
                    for r in reader.execute(
                        "SELECT source_declaration_id, amount FROM exposed.funding_entries"
                    )
                }

        with connect(url) as conn:
            yield PostgresDeclarationStore(conn), amounts


def test_declaration_store_publishes_member_writes_together_and_rolls_back_before_retry(
    declaration_store,
):
    store, amounts = declaration_store
    source = MemoryDeclarationSource()
    source.add(
        DeclarationDraft(
            id=101,
            member_source_id=1,
            category_id=3,
            category_name="Donations",
            payer="Donor",
            funding=(
                FundingEntry(
                    funder_name="Donor", amount=Decimal("100"), currency="GBP", payment_type=None
                ),
            ),
        )
    )
    refresh_declarations(TERM_START, source, store)
    assert amounts() == {101: Decimal("100")}
    old_draft = source.drafts[101]
    assert isinstance(old_draft, DeclarationDraft)
    new_draft = DeclarationDraft(
        **{
            **old_draft.model_dump(),
            "funding": (
                FundingEntry(
                    funder_name="Donor", amount=Decimal("200"), currency="GBP", payment_type=None
                ),
            ),
        }
    )

    class FailingSource(MemoryDeclarationSource):
        def declarations(self, member_id):
            yield from super().declarations(member_id)
            if member_id == 1:
                assert amounts() == {101: Decimal("100")}
                raise SourceError("later source failure")

    failing = FailingSource()
    failing.add(new_draft)
    with pytest.raises(ImportFailed, match="later source failure"):
        refresh_declarations(TERM_START, failing, store)
    assert amounts() == {101: Decimal("100")}
    retry = MemoryDeclarationSource()
    retry.add(new_draft)
    refresh_declarations(TERM_START, retry, store)
    assert amounts() == {101: Decimal("200")}


@pytest.mark.parametrize("failure", [SourceError("later member failed"), KeyboardInterrupt()])
def test_completed_member_is_visible_and_survives_later_member_failure(declaration_store, failure):
    store, amounts = declaration_store

    class FailingSource(MemoryDeclarationSource):
        def declarations(self, member_id):
            if member_id == 2:
                assert amounts() == {101: Decimal("100")}
            yield from super().declarations(member_id)
            if member_id == 2:
                assert amounts() == {101: Decimal("100")}
                raise failure

    source = FailingSource()
    for member in (1, 2):
        source.add(
            DeclarationDraft(
                id=100 + member,
                member_source_id=member,
                category_id=3,
                category_name="Donations",
                payer="Donor",
                funding=(
                    FundingEntry(
                        funder_name="Donor",
                        amount=Decimal("100"),
                        currency="GBP",
                        payment_type=None,
                    ),
                ),
            )
        )
    with pytest.raises(ImportFailed) as error:
        refresh_declarations(TERM_START, source, store)
    assert error.value.__cause__ is failure
    assert error.value.interrupted == isinstance(failure, KeyboardInterrupt)
    assert amounts() == {101: Decimal("100")}
import json

import httpx
import pytest

from exposed.cli import main, run_cli
from exposed.declaration_api import INTERESTS_BASE_URL
from tests.declaration_fakes import DeclarationsFixture, declaration, money
from tests.fakes import TERM_START, ParliamentFixture
from tests.test_importer import run as import_members


@pytest.mark.integration
@pytest.mark.parametrize("failure, exit_code", [(None, 0), (503, 1), ("interrupt", 130)])
def test_declaration_command_reports_normal_results(
    database_url, monkeypatch, capsys, caplog, failure, exit_code
):
    import_members(database_url, ParliamentFixture(1))
    fixture = DeclarationsFixture(declaration(fields=[money("janky amount")]), declaration(102))

    def handle(request):
        assert str(request.url).startswith(INTERESTS_BASE_URL)
        if failure == "interrupt":
            raise KeyboardInterrupt
        if isinstance(failure, int):
            return httpx.Response(failure)
        return fixture.handle(request)

    # Replace only the outbound HTTP transport; CLI, client, importer and DB are real.
    original_client = httpx.Client
    monkeypatch.setattr(
        httpx, "Client", lambda **kw: original_client(**kw, transport=httpx.MockTransport(handle))
    )
    monkeypatch.setenv("DATABASE_URL", database_url)
    monkeypatch.setenv("PARLIAMENT_TERM_START", TERM_START.isoformat())

    assert main(["import-declarations"]) == exit_code
    summary = json.loads(capsys.readouterr().out)
    assert summary["status"] == ("succeeded" if exit_code == 0 else "failed")
    if exit_code == 0:
        assert "Rejected declaration 101" in caplog.text
        assert "janky amount" in caplog.text
        assert summary["declarations"] == 1


@pytest.mark.parametrize("interrupted", [False, True])
def test_declaration_cli_uses_injected_command_and_maps_failures(
    interrupted,
    monkeypatch,
    tmp_path,
    capsys,
):
    from exposed.core.errors import ImportFailed

    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("DATABASE_URL", "postgresql://configured")
    monkeypatch.setenv("PARLIAMENT_TERM_START", TERM_START.isoformat())

    def members(url, term):
        pytest.fail("Declaration command must not call the member use case")

    def declarations(url, term):
        assert url == "postgresql://configured"
        assert term == TERM_START
        raise ImportFailed("Declaration refresh failed", interrupted=interrupted)

    assert run_cli(["import-declarations"], members, run_declarations=declarations) == (
        130 if interrupted else 1
    )
    assert json.loads(capsys.readouterr().out) == {
        "status": "failed",
        "error": "Declaration refresh failed",
    }
import json
from datetime import date

import httpx
import pytest

from exposed.cli import main, run_cli
from exposed.core.errors import ImportFailed, StorageError
from tests.fakes import ParliamentFixture


def test_cli_passes_explicit_configuration_to_the_refresh_and_prints_its_summary(
    monkeypatch, tmp_path, capsys
):
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("DATABASE_URL", "postgresql://configured-database")
    monkeypatch.setenv("PARLIAMENT_TERM_START", "2020-01-01")
    (tmp_path / ".env").write_text("DATABASE_URL=postgresql://file-database\n")

    def run(database_url: str, term_start: date) -> dict[str, object]:
        assert database_url == "postgresql://configured-database"
        assert term_start == date(2024, 7, 4)
        return {"status": "succeeded", "members": 2}

    status = run_cli(["import-members", "--term-start", "2024-07-04"], run)

    assert status == 0
    assert json.loads(capsys.readouterr().out) == {"status": "succeeded", "members": 2}


@pytest.mark.parametrize(
    ("failure", "status", "message"),
    [
        (ImportFailed("Source unavailable"), 1, "Source unavailable"),
        (ImportFailed("Import interrupted", interrupted=True), 130, "Import interrupted"),
        (KeyboardInterrupt(), 130, "Interrupted"),
        (
            StorageError("Database operation failed (OperationalError, SQLSTATE unknown)"),
            1,
            "Database operation failed (OperationalError, SQLSTATE unknown)",
        ),
    ],
)
def test_cli_preserves_failure_json_and_exit_codes(
    failure, status, message, monkeypatch, tmp_path, capsys
):
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("DATABASE_URL", "postgresql://configured-database")

    def run(database_url: str, term_start: date) -> dict[str, object]:
        raise failure

    assert run_cli(["import-members", "--term-start", "2024-07-04"], run) == status
    assert json.loads(capsys.readouterr().out) == {"status": "failed", "error": message}


@pytest.mark.parametrize(
    ("database_url", "term_start"),
    [
        (None, "2024-07-04"),
        ("postgresql://configured", None),
        ("postgresql://configured", "20240704"),
        ("postgresql://configured", "2024-02-30"),
    ],
)
def test_invalid_cli_configuration_exits_before_starting_a_refresh(
    database_url, term_start, monkeypatch, tmp_path, capsys
):
    monkeypatch.chdir(tmp_path)
    for key, value in {"DATABASE_URL": database_url, "PARLIAMENT_TERM_START": term_start}.items():
        if value is None:
            monkeypatch.delenv(key, raising=False)
        else:
            monkeypatch.setenv(key, value)

    def run(database_url: str, term_start: date) -> dict[str, object]:
        pytest.fail("Invalid CLI configuration must not start a refresh")

    with pytest.raises(SystemExit) as error:
        run_cli(["import-members"], run)

    assert error.value.code == 2
    assert capsys.readouterr().out == ""


@pytest.mark.integration
def test_production_cli_wiring_refreshes_members_in_postgresql(
    database_url, monkeypatch, tmp_path, capsys
):
    fixture = ParliamentFixture(2)
    fixture.leave(2, lords=True)
    client_type = httpx.Client

    def local_client(*args, **kwargs):
        kwargs["transport"] = httpx.MockTransport(fixture.handle)
        return client_type(*args, **kwargs)

    # Substitute only the external HTTP transport; run the real CLI, composition,
    # source adapter, refresh and PostgreSQL adapter against a temporary database.
    monkeypatch.setattr(httpx, "Client", local_client)
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("DATABASE_URL", database_url)
    monkeypatch.setenv("PARLIAMENT_TERM_START", "2024-07-04")

    assert main(["import-members"]) == 0
    result = json.loads(capsys.readouterr().out)
    assert (
        result["status"],
        result["inserted"],
        result["current_commons"],
        result["former_commons"],
    ) == ("succeeded", 2, 1, 1)

